import { useState, useCallback, memo, useEffect } from 'react';
import '../styles/searchForm.css';

const cities = [
  'Москва', 'Санкт-Петербург', 'Казань', 'Новосибирск',
  'Екатеринбург', 'Краснодар', 'Сочи', 'Нижний Новгород', 'Стерлитамак'
];

const SearchForm = memo(({ onSearch, onInputChange, wide, isLoading }) => {
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [date, setDate] = useState('');
  const [showFromSuggestions, setShowFromSuggestions] = useState(false);
  const [showToSuggestions, setShowToSuggestions] = useState(false);
  const [isFormFocused, setIsFormFocused] = useState(false);

  const handleFormFocus = useCallback(() => {
    setIsFormFocused(true);
  }, []);

  const handleFormBlur = useCallback(() => {
    setIsFormFocused(false);
  }, []);

  const handleSubmit = useCallback((e) => {
    e.preventDefault();
    if (!isLoading) {
      onSearch({ from, to, date });
    }
  }, [from, to, date, onSearch, isLoading]);

  const filterCities = useCallback((input) => 
    cities.filter(city =>
      city.toLowerCase().includes(input.toLowerCase())
    ), []);

  const handleInput = useCallback((e) => {
    onInputChange();
    const { name, value } = e.target;
    if (name === 'from') setFrom(value);
    if (name === 'to') setTo(value);
    if (name === 'date') setDate(value);
  }, [onInputChange]);

  return (
    <div className="search-form-container">
      <form 
        onSubmit={handleSubmit} 
        className={`search-form ${wide && !isFormFocused ? 'wide' : ''}`}
        onFocus={handleFormFocus}
        onBlur={handleFormBlur}
      >
        <h2 className="form-title">Поиск билетов</h2>
        
        <div className="form-grid">
          {/* ...остальные элементы формы без изменений... */}
        </div>

        <button 
          type="submit" 
          className="search-button"
          disabled={!from || !to || isLoading}
        >
          {isLoading ? 'Загрузка...' : 'Найти билеты'}
        </button>
      </form>
    </div>
  );
});

export default SearchForm;
